const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '7' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '7:3' }
    ];
  },
  render: function (input, metrics) {
    var baseline = visualSdk.polyline([[80, 140], [520, 140]]);
    var leftTick = visualSdk.polyline([[80, 126], [80, 154]]);
    var splitTick = visualSdk.polyline([[388, 126], [388, 154]]);
    var rightTick = visualSdk.polyline([[520, 126], [520, 154]]);
    return {
      schemaVersion: 1,
      sceneId: 'ratio-7-3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: input.viewport.widthDu, height: input.viewport.heightDu },
      paths: [
        { id: 'baseline', commands: baseline },
        { id: 'leftTick', commands: leftTick },
        { id: 'splitTick', commands: splitTick },
        { id: 'rightTick', commands: rightTick }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'baseline', fill: '#26354a', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'leftTick', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'splitTick', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'rightTick', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: 234, y: 120 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: 454, y: 120 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: 300, y: 70 }, hAlign: 'center', vAlign: 'bottom', color: '#b23a2b' }
        ]
      }
    };
  }
};
